{
  "goal": "Establish a Bun-based CLI entrypoint for TaskForge with a minimal, typed command surface and basic argument parsing.",
  "decisions": [
    "Use Bun as the runtime and expose a src/cli.ts entrypoint",
    "Implement a small, typed command registry and a central dispatcher",
    "Support --help, -h, --version, -v and unknown-command error handling",
    "Wire a package.json bin entry so it can be run as taskforge and via bun run"
  ],
  "risks": [
    "Bun/Node parseArgs compatibility edge cases may require a fallback",
    "Choosing a parser too early could constrain future nested subcommands",
    "Bin packaging differences between local Bun run and installed CLI usage"
  ],
  "snippets": [
    "#!/usr/bin/env bun
// src/cli.ts
type Command = {
  name: string;
  description: string;
  run: (args: string[]) => void;
};
const commands: Command[] = [
  { name: 'help', description: 'Show help', run: () => console.log('usage: taskforge [cmd]') },
  { name: 'version', description: 'Print version', run: () => console.log('TaskForge v0.1.0') },
];
const args = process.argv.slice(2);
const [cmd] = args;
const found = commands.find(c => c.name === (cmd ?? ''));
if (!found) { console.error(`Unknown command: ${cmd}`); process.exit(1); }
found.run(args.slice(1));",
    "// Central registry + dispatcher (typed):
type CommandSpec = { name: string; description: string; run: (args: string[]) => void; };
const registry: CommandSpec[] = [
  { name: 'help', description: 'Show help', run: () => console.log('usage: taskforge [cmd]') },
  { name: 'version', description: 'Version', run: () => console.log('TaskForge v0.1.0') },
];
const argv = process.argv.slice(2);
const [head, ...rest] = argv;
const entry = registry.find(c => c.name === head);
if (!entry) { console.error(`Unknown command: ${head}`); process.exit(1); }
entry.run(rest);",
    "{
  "name": "taskforge",
  "version": "0.1.0",
  "type": "module",
  "bin": { "taskforge": "./src/cli.ts" },
  "scripts": { "start": "bun run src/cli.ts" }
}"
